#include <stdlib.h>

/* A 2x2x2 cube with one corner held fixed: seven cubies, each with a place
 * p and a twist o of 0, 1 or 2. */
enum { C = 7, O = 729, N = 3674160 };
typedef struct {
    unsigned char p[C], o[C];
} state_t;

/* One clockwise quarter turn of face f: 0 is R, 1 is B, 2 is D. */
static state_t turn(state_t s, int f)
{
    static const char map[][15] = {
        "14203561202100",
        "01245630001212",
        "02531460000000",
    };
    state_t t;
    for (int i = 0; i < C; ++i) {
        int j = map[f][i] - '0';
        t.p[i] = s.p[j];
        t.o[i] = (s.o[j] + map[f][i + C] - '0') % 3;
    }
    return t;
}

/* A dense index in 0..N-1 for a valid position; the solved one is 0. */
static size_t rank_state(state_t s)
{
    size_t p = 0, o = 0;
    for (int i = 0; i < C; ++i) {
        int n = 0;
        for (int j = i + 1; j < C; ++j)
            n += s.p[j] < s.p[i]; /* TASK_OPTIMIZE_RANK */
        p = p * (C - i) + n;
        if (i < 6)
            o = o * 3 + s.o[i];
    }
    return p * O + o;
}

/* step[r] is 1 plus the move that takes position r one step toward solved:
 * face * 3 plus the quarter turns it needs, less one. */

/* Breadth-first search outward from the solved cube. */
static unsigned char *build_table(void)
{
    unsigned char *step = calloc(N, 1);
    /* TASK_OPTIMIZE_QUEUE */
    state_t *queue = malloc(sizeof(*queue) * N);
    size_t head = 0, tail = 1;
    queue[0] = (state_t) {{0, 1, 2, 3, 4, 5, 6}, {0}};
    while (head < tail) {
        state_t from = queue[head++];
        for (int f = 0; f < 3; ++f) {
            state_t to = from;
            for (int n = 0; n < 3; ++n) {
                /* TASK_OPTIMIZE_TABLES */
                size_t rank = rank_state(to = turn(to, f));
                if (rank && !step[rank]) {
                    step[rank] = f * 3 + 3 - n;
                    queue[tail++] = to;
                }
            }
        }
    }
    free(queue);
    return step;
}

int solveLength(char* code)
{
    state_t s;
    int moves = 0;
    for (int i = 0; i < C; ++i) {
        s.p[i] = code[i] - '1';
        s.o[i] = code[i + C] - '1';
    }
    /* TASK_OPTIMIZE_REUSE */
    unsigned char *step = build_table();
    /* No position needs more than 11 turns, so a table that sends the walk
     * in circles ends it here instead of hanging. */
    for (size_t rank; moves <= 11 && (rank = rank_state(s)); ++moves) {
        int move = step[rank] - 1;
        for (int n = move % 3 + 1; n--;)
            s = turn(s, move / 3);
    }
    free(step);
    return moves;
}

