#include <stdint.h>
#include <stdlib.h>
#include <string.h>

enum { CUBIES = 7, PERMS = 5040, TWISTS = 729, STATES = PERMS * TWISTS };

typedef struct {
    uint8_t p[CUBIES], o[CUBIES];
} state_t;

/* Destination i takes its cubie from source[face][i]. */
static const uint8_t source[3][CUBIES] = {
    {1, 4, 2, 0, 3, 5, 6}, {0, 1, 2, 4, 5, 6, 3}, {0, 2, 5, 3, 1, 4, 6}};
static const uint8_t twist[3][CUBIES] = {
    {1, 2, 0, 2, 1, 0, 0}, {0, 0, 0, 1, 2, 1, 2}, {0, 0, 0, 0, 0, 0, 0}};

static state_t quarter(state_t s, int face)
{
    state_t t;
    for (int i = 0; i < CUBIES; ++i) {
        t.p[i] = s.p[source[face][i]];
        t.o[i] = (s.o[source[face][i]] + twist[face][i]) % 3;
    }
    return t;
}

static uint32_t rank_state(const state_t *s)
{
    uint32_t p = 0, o = 0;
    for (int i = 0; i < CUBIES; ++i) {
        int smaller = 0;
        for (int j = i + 1; j < CUBIES; ++j)
            smaller += s->p[j] < s->p[i];
        p = p * (CUBIES - i) + smaller;
    }
    for (int i = 0; i < 6; ++i)
        o = o * 3 + s->o[i];
    return p * TWISTS + o;
}

static void unrank_state(uint32_t rank, state_t *s)
{
    uint8_t free_[CUBIES] = {0, 1, 2, 3, 4, 5, 6};
    uint32_t p = rank / TWISTS, o = rank % TWISTS, f = 720;
    int sum = 0;
    for (int i = 0; i < CUBIES; ++i) {
        int q = p / f;
        p %= f;
        s->p[i] = free_[q];
        for (int j = q; j + 1 < CUBIES - i; ++j)
            free_[j] = free_[j + 1];
        if (i < 5)
            f /= 6 - i;
    }
    for (int i = 5; i >= 0; --i) {
        s->o[i] = o % 3;
        sum += s->o[i];
        o /= 3;
    }
    s->o[6] = (3 - sum % 3) % 3;
}

/* back[r]: the move (face * 3 + quarter turns - 1) that takes r a step home. */
static uint8_t *build_table(void)
{
    static uint16_t perm[3][PERMS], twst[3][TWISTS];
    uint8_t *back = malloc(STATES);
    uint32_t *queue = malloc(sizeof(*queue) * STATES);
    uint32_t head = 0, tail = 1;
    state_t s;
    for (int r = 0; r < PERMS; ++r) {
        unrank_state(r * TWISTS, &s);
        for (int f = 0; f < 3; ++f) {
            state_t n = quarter(s, f);
            perm[f][r] = rank_state(&n) / TWISTS;
        }
    }
    for (int r = 0; r < TWISTS; ++r) {
        unrank_state(r, &s);
        for (int f = 0; f < 3; ++f) {
            state_t n = quarter(s, f);
            twst[f][r] = rank_state(&n) % TWISTS;
        }
    }
    memset(back, 255, STATES);
    back[0] = 0;
    queue[0] = 0;
    while (head < tail) {
        uint32_t here = queue[head++];
        for (int f = 0; f < 3; ++f) {
            uint32_t p = here / TWISTS, o = here % TWISTS;
            for (int turn = 0; turn < 3; ++turn) {
                p = perm[f][p];
                o = twst[f][o];
                uint32_t there = p * TWISTS + o;
                if (back[there] == 255) {
                    back[there] = f * 3 + (2 - turn);
                    queue[tail++] = there;
                }
            }
        }
    }
    free(queue);
    return back;
}

int solveLength(char* code)
{
    static uint8_t *back;
    state_t s;
    int moves = 0;
    if (!back)
        back = build_table();
    for (int i = 0; i < CUBIES; ++i) {
        s.p[i] = code[i] - '1';
        s.o[i] = code[i + CUBIES] - '1';
    }
    for (uint32_t r; (r = rank_state(&s)) != 0; ++moves)
        for (int t = 0; t <= back[r] % 3; ++t)
            s = quarter(s, back[r] / 3);
    return moves;
}
